@startuml

class SensorController {
  + apartmentInfo : string
  + inhabitants : User[]
}

class User {
  + username : string
  + password : string
  + email : string
}

class Apartment {
  + address : string
}

class Room {
  + description : string
}

class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
  + threshold : float
}

class TemperatureSensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor {
  + totalConsumption : float
}

class SensorValue {
  + timestamp : datetime
  + value : float
}

class EMonitor {
  + checkThresholds() : boolean
  + sendAlert() : void
}

enum Unit {
  CELSIUS
  WATT
}

SensorController "1" o-- "1" Apartment
Apartment "1" *-- "2..*" Room
Room "1" *-- "*" Sensor
Sensor "1" *-- "*" SensorValue
Sensor "1" *-- "1" Unit
TemperatureSensor --|> Sensor
PowerSensor --|> Sensor
User "*" -- "1" SensorController : logs_on
User "0..1" -- "1" SensorController : administrator
User "1" -- "*" Sensor : queries
SensorController "1" -- "1" EMonitor : attached_to
EMonitor "1" -- "*" Sensor : checks_thresholds
EMonitor "1" -- "1" Apartment : sends_alert_to

